mapper.select:
/* selectMasterMpStSellerApResultList */ SELECT X.AGENT , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.AGENT) AS AGENT_NAME , Y.CODE AS TEAM , Y.TEXT1 AS TEAM_NAME , M01+M02+M03+M04+M05+M06+M07+M08+M09+M10+M11+M12 AS TOTAL , M01 AS JAN , M02 AS FEB , M03 AS MAR , M04 AS APR , M05 AS MAY , M06 AS JUN , M07 AS JUL , M08 AS AUG , M09 AS SEP , M10 AS OCT , M11 AS NOV , M12 AS DEC FROM BNTMIS_AGENT X, ICOMCOD2 Y WHERE 1=1 AND X.YYYY= #{st_year}
AND X.AGENT = #{st_agent_code}
AND X.KEP_DEPT = #{st_user_dept}
AND Y.COMPANY_CODE(+) = 'KRKORE0001' AND Y.TYPE(+) = 'C001' AND Y.CODE(+) = X.KEP_DEPT ORDER BY AGENT_NAME, Y.VALUE1
